head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16602";
scwin.filebox = null;
scwin.doubleSubmitFlag = false;
scwin.uploadFileNum = 1;
scwin.result = null;
scwin.upd_attachUploadFile1 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.filebox = $c.util.getComponent('filebox');
        scwin.upd_attachUploadFile1 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachUploadFile1') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachUploadFile1"]');
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16602.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "txt_text46", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'HWP'); } }, { id: "txt_text49", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLS' || (dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLSX'); } }, { id: "txt_text52", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'DOC'); } }, { id: "txt_text55", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PPT'); } }, { id: "txt_text58", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_59", fn: function(){ return (!(((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'HWP') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLS' || (dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLSX') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'DOC') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PPT') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PDF'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_41", entity: "dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO", countIds: [], cells: [{ childId: "__rc4", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc6", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc9", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(dma_comSprtSvcApplVO.get("consultPd")) + "일"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnRegister();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_5_onsubmit
 * @description form_5 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_5_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16602.form_5_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnFileDown_onclick
 * @description btn_fnFileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnFileDown_onclick = async function(e){
    try {
        await scwin.fnFileDown('' + dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "contnId") + '','' + dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "contnAttachSeq") + '','' + dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "attachFileNm") + '','' + dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "wrtDdtm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16602.btn_fnFileDown_onclick' }); }
};

/**
 * @method
 * @name button_92_onclick
 * @description 「추가」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.button_92_onclick = async function(e){
    try {
        await scwin.fnFilePlus()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16602.button_92_onclick' }); }
};

/**
 * @method
 * @name button_93_onclick
 * @description 「삭제」 클릭 이벤트
