 */
scwin.button_93_onclick = function(e){
    try {
        scwin.fnFileMinus()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16602.button_93_onclick' }); }
};

/**
 * @method
 * @name btn_fnRegister_onclick
 * @description 「신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
