 */
scwin.btn_fnRegister_onclick = async function(e){
    try {
        await scwin.fnRegister()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16602.btn_fnRegister_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16602.btn_fnSearch_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch
 * @description fn Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        target: "dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnRegister
 * @description fn Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnRegister = async function () {
    const sbmOptions = {
        id: "tx_fnRegister",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnRegisterReq",
        target: "dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnApplComCntChk
 * @description fn Appl Com Cnt Chk 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnApplComCntChk = async function () {
    const sbmOptions = {
        id: "tx_fnApplComCntChk",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnApplComCntChkReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fnFileDown
 * @description fn File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnFileDown = async function () {
    try { return await $c.data.downFile("/support/comSprtSvcFileDownload.do", "", ($c.util.getComponent("dma_fnFileDownReq") ? $c.util.getComponent("dma_fnFileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $("input[name='method']").val("comSprtSvcApplList");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do") */
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    const nr = await scwin.tx_fnSearch();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil16601/jldfil16601.xml", { "method": "comSprtSvcApplList" });
    }
};

/**
 * @method
 * @name doubleSubmitCheck
 * @description double Submit Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.doubleSubmitCheck = function () {
    if (scwin.doubleSubmitFlag) {
        return scwin.doubleSubmitFlag;
    } else {
        scwin.doubleSubmitFlag = true;
        return false;
    }
};

/**
 * @method
 * @name fnRegister
 * @description fn Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnRegister = async function () {
    const bl = await scwin.fnApplComCntChk($c.util.getComponent('ipt_comSchdlId').getValue());
    if (bl === 'false') {
        await $c.win.alert('신청가능한 법인수를 초과하였습니다.\n다음에 신청해주세요.');
        return;
    }
    const consultHopTmVal = $("input[name='consultHopTmVal']");
    if (consultHopTmVal.val() === '' || consultHopTmVal == null) {
        await $c.win.alert("컨설팅 희망시기를 입력하세요.");
        consultHopTmVal.focus();
        return;
    }
    const chrgNm = $("input[name='chrgNm']");
    if (chrgNm == null || chrgNm == null) {
        await $c.win.alert("담당자 정보가 없습니다.");
        return;
    }
    for (let i = 0; i < chrgNm.length; i++) {
        const chrgNmEq = chrgNm.eq(i);
        if (chrgNm.eq(0).attr("value") == null || chrgNm.eq(0).attr("value") === "") {
            await $c.win.alert("담당자 1 성명을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='jobtitlNm']").eq(0).attr("value") == null || $("input[name='jobtitlNm']").eq(0).attr("value") === "") {
            await $c.win.alert("담당자 1 직위를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='telNo']").eq(0).attr("value") == null || $("input[name='telNo']").eq(0).attr("value") === "") {
            await $c.win.alert("담당자 1 연락처를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='telNo']").eq(i).attr("value") !== "") {
            if (scwin.fnTelNoCheck($("input[name='telNo']").eq(i).attr("value"))) {
                await $c.win.alert("담당자 " + (i + 1) + " 연락처 형식이 틀렸습니다.\nex)02-0000-0000");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        if ($("input[name='cellphoneNo']").eq(0).attr("value") == null || $("input[name='cellphoneNo']").eq(0).attr("value") === "") {
            await $c.win.alert("담당자 1 핸드폰을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='cellphoneNo']").eq(i).attr("value") !== "") {
            if (scwin.fnCellPhoneCheck($("input[name='cellphoneNo']").eq(i).attr("value"))) {
                await $c.win.alert("담당자 " + (i + 1) + " 핸드폰 형식이 틀렸습니다.\nex)010-0000-0000");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        if ($("input[name='email']").eq(0).attr("value") == null || $("input[name='email']").eq(0).attr("value") === "") {
            await $c.win.alert("담당자 1 이메일을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='email']").eq(i).attr("value") !== "") {
            if (scwin.fnEmailCheck($("input[name='email']").eq(i).attr("value"))) {
                await $c.win.alert("담당자 " + (i + 1) + " 이메일 형식이 틀렸습니다.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
    }
    const file = $("input[type='file']");
    let fCnt = 0;
    let fNmLength = 0;
    let fType = 0;
    let fSize = 0;
    for (let i = 0; i < file.length; i++) {
        if (file.eq(i).attr("value") !== '' && file.eq(i).attr("value") != null) {
            fCnt++;
            fNmLength += scwin.fnFileNmLengthChk(file.eq(i).attr("value"));
            fType += scwin.fnFileTypeChk(file.eq(i).attr("value"));
            fSize += $c.util.getComponent("attachUploadFile" + (i + 1)).files[0].size;
        }
    }
    if (fCnt === 0) {
        await $c.win.alert('사전조사표를 첨부하세요.');
        return;
    }
    if (fNmLength > 0) {
        await $c.win.alert('파일명 길이가 80byte 초과된 파일이 ' + fNmLength + '개 있습니다.');
        return;
    }
    if (fType > 0) {
        await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + fType + '개 있습니다.\n사용가능 확장자 : doc, docx, xls, xlsx, ppt, pptx, hwp, pdf, zip, jpg, jpeg, gif, png, bmp, txt');
        return;
    }
    if (fSize > (1024 * 1024 * 30)) {
        await $c.win.alert('전체 파일용량은 30MB를 넘을수 없습니다.');
        return;
    }
    if ($("#ipt_perInfoChk1").is(":checked") !== true) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해야 신청가능합니다.");
        $c.util.getComponent("ipt_perInfoChk1").focus();
        return;
    }
    if ($("#ipt_perInfoChk2").is(":checked") !== true) {
        await $c.win.alert("기업지원서비스 신청관련 사안에 동의해야 신청가능합니다.");
        $c.util.getComponent("ipt_perInfoChk2").focus();
        return;
    }
    if (scwin.doubleSubmitCheck()) {
        return;
    }
    $("input[name='method']").val("comSprtSvcApplWrite");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do") */
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnRegister();
};

/**
 * @method
 * @name fnTelNoCheck
 * @description fn Tel No Check 처리
 * @param {*} ipt_telNo ipt_telNo
 * @returns {void}
 * @hidden N
 */
scwin.fnTelNoCheck = function (ipt_telNo) {
    const regTelNo = /^(0[2-8][0-5]?)-?([1-9]{1}[0-9]{2,3})-?([0-9]{4})$/;
    if (!regTelNo.test(ipt_telNo)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnCellPhoneCheck
 * @description fn Cell Phone Check 처리
 * @param {*} cellPhoneNum cellPhoneNum
 * @returns {void}
 * @hidden N
 */
scwin.fnCellPhoneCheck = function (cellPhoneNum) {
    const regPhone = /(01[0|1|6|7|8|9])[-](\d{3}|\d{4})[-](\d{4}$)/g;
    if (!regPhone.test(cellPhoneNum)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnEmailCheck
 * @description fn Email Check 처리
 * @param {*} ipt_email ipt_email
 * @returns {void}
 * @hidden N
 */
scwin.fnEmailCheck = function (ipt_email) {
    const mailexp = /^[_a-zA-Z0-9-\.]+@[\.a-zA-Z0-9-]+\.[a-zA-Z]+$/;
    if (!mailexp.test(ipt_email)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnFileNmLengthChk
 * @description fn File Nm Length Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fnFileNmLengthChk = function (val) {
    const fVal = val.split("\\");
    const fNm = fVal[fVal.length - 1];
    let returnVal = 0;
    if (scwin.fnGetByte(fNm) > 80) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fnGetByte
 * @description fn Get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.fnGetByte = function (_obj) {
    const sTmpCntnt = new String(_obj);
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            inc = 1;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
};

/**
 * @method
 * @name fnFileTypeChk
 * @description fn File Type Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fnFileTypeChk = function (val) {
    const isFileType = ["doc", "docx", "xls", "xlsx", "ppt", "pptx", "hwp", "pdf", "zip", "jpg", "jpeg", "gif", "png", "bmp", "txt"];
    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt === 0) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fnFileDown
 * @description fn File Down 처리
 * @param {String} contnId contnId
 * @param {*} contnAttachSeq contnAttachSeq
 * @param {String} attachFileNm attachFileNm
 * @param {*} wrtDdtm wrtDdtm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnFileDown = async function (contnId, contnAttachSeq, attachFileNm, wrtDdtm) {
    $c.util.getComponent('dma_fnSearchReq').set('method', 'comSprtSvcAttachFile');
    $c.util.getComponent('dma_fnSearchReq').set('contnId', contnId);
    $c.util.getComponent('dma_fnSearchReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_fnSearchReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_fnSearchReq').set('wrtDdtm', wrtDdtm);
    (document.fileDownForm || { elements: [] }).action = '/support/comSprtSvcFileDownload.do';
    await scwin.tx_fnFileDown();
};

/**
 * @method
 * @name fnFilePlus
 * @description fn File Plus 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnFilePlus = async function () {
    if (scwin.uploadFileNum >= 10) {
        await $c.win.alert("첨부파일은 10개까지 가능합니다.");
        return;
    }
    scwin.uploadFileNum++;
    const txt = '<input type="file" name="attachUploadFile[' + scwin.uploadFileNum + ']" id="attachUploadFile' + scwin.uploadFileNum + '" class="w320" />';
    const addedDiv = document.createElement("div");
    addedDiv.id = "fileDiv" + scwin.uploadFileNum;
    addedDiv.style.paddingTop = "3px";
    addedDiv.innerHTML = txt;
    scwin.filebox.appendChild(addedDiv);
};

/**
 * @method
 * @name fnFileMinus
 * @description fn File Minus 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnFileMinus = function () {
    if (scwin.uploadFileNum > 1) {
        const addedDiv = $c.util.getComponent("fileDiv" + scwin.uploadFileNum);
        scwin.filebox.removeChild(addedDiv);
        scwin.uploadFileNum--;
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name fnApplComCntChk_done
 * @description fn Appl Com Cnt Chk done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnApplComCntChk_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    bl = scwin.result.returnVal;
};

/**
 * @method
 * @name fnApplComCntChk
 * @description fn Appl Com Cnt Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnApplComCntChk = async function () {
    const r = await scwin.tx_fnApplComCntChk();
    try {
        scwin.fnApplComCntChk_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil16602.fnApplComCntChk' });
    }
    return r;
};
